export const siteBuildingRoomSchema = z.object({
  id: z.string().min(1).max(64),
  name: z.string().min(1).max(128),
  kind: buildingRoomKindSchema,
  x: z.tuple([z.number().finite().min(0), z.number().finite().min(0)]).refine(([x0, x1]) => x0 < x1, 'room x[0] must be < x[1]'),
  z: z.tuple([z.number().finite().min(0), z.number().finite().min(0)]).refine(([z0, z1]) => z0 < z1, 'room z[0] must be < z[1]'),
}).strict();

export const siteBuildingFloorSchema = z.object({
  level: z.number().int().min(1).max(200),
  label: z.string().min(1).max(128),
  height: z.number().finite().positive().max(30),
  rooms: z.array(siteBuildingRoomSchema).min(1).max(200),
}).strict().superRefine((floor, ctx) => {
  const seen = new Set<string>();
  for (const room of floor.rooms) {
    if (seen.has(room.id)) {
      ctx.addIssue({ code: 'custom', message: `duplicate room id ${room.id} on floor ${floor.level}` });
      return;
    }
    seen.add(room.id);
  }
});

export const siteBuildingPlanSchema = z.object({
  name: z.string().min(1).max(128),
  width: z.number().finite().positive().max(1000),
  depth: z.number().finite().positive().max(1000),
  floors: z.array(siteBuildingFloorSchema).min(1).max(100),
}).strict().superRefine((plan, ctx) => {
  const levels = new Set<number>();
  for (const floor of plan.floors) {
    if (levels.has(floor.level)) {
      ctx.addIssue({ code: 'custom', message: `duplicate floor level ${floor.level}` });
      return;
    }
    levels.add(floor.level);
    for (const room of floor.rooms) {
      if (room.x[1] > plan.width || room.z[1] > plan.depth) {
        ctx.addIssue({ code: 'custom', message: `room ${room.id} exceeds building bounds (${plan.width}x${plan.depth})` });
        return;
      }
    }
  }
});

