  reasons?: Array<'OUT_OF_RANGE' | 'SPIKE' | 'SENTINEL' | 'FLATLINE' | 'DERIVED_INPUT' | 'LOW_CONFIDENCE' | 'SOURCE_UNTRUSTED' | 'PHYSICS_WET_BULB_DRY' | 'PHYSICS_WET_BULB_CONDENSER' | 'PHYSICS_POWER' | 'PHYSICS_COP' | 'PHYSICS_CHW_DIRECTION' | 'PHYSICS_CW_DIRECTION' | 'PHYSICS_HEAT_BALANCE' | 'PROBE_OFFSET'>;
